from collections import Counter
def read_fastq(path):
    reads=[]
    with open(path) as fh:
        while True:
            h=fh.readline()
            if not h: break
            s=fh.readline().strip(); fh.readline(); fh.readline()
            if s: reads.append(s)
    return reads
exo=read_fastq('inputs/exogenous.mix.reads.q1.exo.fq')
endo=read_fastq('inputs/exogenous.mix.reads.q1.endo.fq')
mix=read_fastq('inputs/exogenous.mix.reads.q1.mix.fq')

def kmer_prevalence(reads,k):
    cnt=Counter()
    for r in reads:
        for x in set(r[i:i+k] for i in range(len(r)-k+1)):
            cnt[x]+=1
    n=len(reads)
    return {x:c/n for x,c in cnt.items()}

def ls(pe,pn,pm, only_mix=False, minprev=0):
    num=den=0.0
    universe=set(pe)|set(pn)|set(pm)
    for x in universe:
        m=pm.get(x,0)
        if only_mix and m==0: continue
        e=pe.get(x,0); n=pn.get(x,0)
        if max(e,n)<minprev: continue
        d=e-n; y=m-n
        num+=d*y; den+=d*d
    return num/den if den>0 else float('nan')

for k in (15,21,25,31,36,41,45):
    pe=kmer_prevalence(exo,k); pn=kmer_prevalence(endo,k); pm=kmer_prevalence(mix,k)
    print(k,'all',round(ls(pe,pn,pm,False),4),'mixonly',round(ls(pe,pn,pm,True),4))
# weighted by prevalence in mix? 
def ls_w(pe,pn,pm):
    num=den=0
    for x in set(pe)|set(pn)|set(pm):
        e=pe.get(x,0); n=pn.get(x,0); m=pm.get(x,0)
        d=e-n; y=m-n
        w=m+1e-6
        num+=w*d*y; den+=w*d*d
    return num/den if den else float('nan')
for k in (21,25,31,36,41,45):
    pe=kmer_prevalence(exo,k); pn=kmer_prevalence(endo,k); pm=kmer_prevalence(mix,k)
    print('w',k,round(ls_w(pe,pn,pm),4))
